WITH parsed AS (SELECT id, customer_id, created_at, coupon_codes, items, attributes, TRANSFORM(FILTER(items, item -> item.promo IS NOT NULL), item -> STRUCT(item.product_id AS pid, ROUND(item.price * 0.9, 2) AS discounted_price)) AS promo_lines, COALESCE(attributes['utm_source'], 'unknown') AS utm_source_or_default, FORALL(items, item -> item.qty <= 5) AS all_small_qty, SIZE(FILTER(items, item -> item.qty >= 3)) AS bulk_lines, ship_to.city AS ship_city FROM carts) SELECT id, coupon_codes, utm_source_or_default, MAX(bulk_lines) OVER (PARTITION BY customer_id ORDER BY created_at, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_max_bulk_lines, AVG(bulk_lines) OVER (PARTITION BY customer_id ORDER BY created_at, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_bulk_lines, SUM(bulk_lines) OVER (PARTITION BY customer_id ORDER BY created_at, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_sum_bulk_lines FROM parsed;
